// Approval evidence must be fetched from Ostrel in this session. Read-only.
@id("wo-fetch-ostrel-approval")
permit (principal, action == Drupe::Action::"Ostrel___get_approval", resource);

// Closing: MAIN only, and only on a current, completed, person-approved Ostrel
// decision for this exact work order. The approval fetch must have completed
// within the last hour. No later REFUSED or OPEN decision for the same job may
// have been recorded since that approval. The approval timestamp itself is not
// in the event schema, so the completed fetch time is used as the bound.
@id("wo-close-main-on-person-approval")
permit (principal, action == Drupe::Action::"MaintData___close_workorder", resource)
when { context.input.site_id == "MAIN" }
when temporal {
  formerly within 1h Drupe::Action::"Ostrel___get_approval"::response{
    eventResource: resource,
    input.site_id: context.input.site_id,
    input.wonum: context.input.wonum,
    output.decision: Drupe::decision::"ACCEPTED",
    output.approver_kind: Drupe::approver_kind::"PERSON"
  }
  && !Drupe::Action::"Ostrel___get_approval"::response{
    eventResource: resource,
    input.site_id: context.input.site_id,
    input.wonum: context.input.wonum,
    output.decision: Drupe::decision::"REFUSED"
  } since within 1h Drupe::Action::"Ostrel___get_approval"::response{
    eventResource: resource,
    input.site_id: context.input.site_id,
    input.wonum: context.input.wonum,
    output.decision: Drupe::decision::"ACCEPTED",
    output.approver_kind: Drupe::approver_kind::"PERSON"
  }
  && !Drupe::Action::"Ostrel___get_approval"::response{
    eventResource: resource,
    input.site_id: context.input.site_id,
    input.wonum: context.input.wonum,
    output.decision: Drupe::decision::"OPEN"
  } since within 1h Drupe::Action::"Ostrel___get_approval"::response{
    eventResource: resource,
    input.site_id: context.input.site_id,
    input.wonum: context.input.wonum,
    output.decision: Drupe::decision::"ACCEPTED",
    output.approver_kind: Drupe::approver_kind::"PERSON"
  }
};

// The agent never approves work orders itself. This forbid is explicit so that
// no other permit can open this path.
@id("wo-agent-never-approves")
forbid (principal, action == Drupe::Action::"MaintData___approve_workorder", resource);
